// void foo(Request, StreamObserver<Response>) is the generated counterpart of Response foo(Request)
private static boolean isGeneratedPair(MethodDescriptor unary, MethodDescriptor serverStream) {
    Class<?>[] streamParams = serverStream.getParameterClasses();
    return streamParams.length > 0
            && Arrays.equals(Arrays.copyOf(streamParams, streamParams.length - 1), unary.getParameterClasses());
}

